<template><main/></template><script>export default {data(){return {settings:{enabled:true,extra:{name:'initial',items:[{value:1}]}},count:0};},
watch:{settings:{deep:true,handler(){this.recount();}}},mounted(){this.load();},beforeDestroy(){},
